css:
.am {font-family:var(--font-sans);-webkit-font-smoothing:antialiased;letter-spacing:var(--tracking-snug);box-sizing:border-box;display:flex;min-width:0;flex-direction:column;padding:8px 0;gap:1.5em;width:100%;font-size:var(--text-markdown)}
.am .sec {position:relative;min-width:0}
.am .md {font-size:var(--text-markdown);line-height:var(--leading-normal);color:var(--color-foreground)}
.am .md p {margin:0}
.am .md p + p, .am .md p + ul, .am .md ul + p {margin-top:.75em}
.am .md ul {margin:.5em 0 0;padding-left:1.25em}
.am .md li + li {margin-top:.25em}
.am .md strong {font-weight:var(--font-weight-semibold)}
.am .md code {font-family:var(--font-mono);font-size:.9em;background:var(--color-secondary);border-radius:var(--radius-sm);padding:1px 4px}
.am .ft {position:absolute;right:0;top:-22px}
